schema.code:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "https://faion.net/schemas/single-channel-bet-selector.json",
  "title": "Single Channel Bet Selector decision record",
  "type": "object",
  "required": ["selected_on", "rubric_location", "working_channel_exists", "icp_sample", "candidates", "outcome", "bet", "no_bet_route", "parking_lot"],
  "additionalProperties": false,
  "definitions": {
    "date": {"type": "string", "pattern": "^[0-9]{4}-[0-9]{2}-[0-9]{2}$"},
    "score": {"type": "integer", "minimum": 1, "maximum": 5},
    "tactic": {"type": "string", "minLength": 12, "not": {"enum": ["social", "outbound", "content", "paid", "ads", "seo", "email", "events", "community", "partnerships", "pr"]}},
    "taxonomy_channel": {"type": "string", "enum": ["targeting_blogs", "publicity", "unconventional_pr", "search_engine_marketing", "social_and_display_ads", "offline_ads", "seo", "content_marketing", "email_marketing", "engineering_as_marketing", "viral_marketing", "business_development", "sales", "affiliate_programs", "existing_platforms", "trade_shows", "offline_events", "speaking_engagements", "community_building"]}
  },
  "properties": {
    "__faion_header__": {"type": ["object", "string"]},
    "selected_on": {"$ref": "#/definitions/date"},
    "rubric_location": {"type": "string", "minLength": 8},
    "working_channel_exists": {"const": false},
    "icp_sample": {
      "type": "object",
      "required": ["paying_customers", "qualified_conversations"],
      "additionalProperties": false,
      "properties": {
        "paying_customers": {"type": "integer", "minimum": 0},
        "qualified_conversations": {"type": "integer", "minimum": 0}
      },
      "anyOf": [
        {"properties": {"paying_customers": {"minimum": 5}}},
        {"properties": {"qualified_conversations": {"minimum": 50}}}
      ]
    },
    "candidates": {
      "type": "array",
      "minItems": 3,
      "maxItems": 6,
      "items": {
        "type": "object",
        "required": ["channel", "taxonomy_channel", "founder_fit", "icp_density", "icp_density_sample", "early_traction", "unsolicited_inbound_count", "total", "clears_bar"],
        "additionalProperties": false,
        "properties": {
          "channel": {"$ref": "#/definitions/tactic"},
          "taxonomy_channel": {"$ref": "#/definitions/taxonomy_channel"},
          "founder_fit": {"$ref": "#/definitions/score"},
          "icp_density": {"$ref": "#/definitions/score"},
          "icp_density_sample": {
            "anyOf": [
              {"type": "null"},
              {
                "type": "object",
                "required": ["observed", "of"],
                "additionalProperties": false,
                "properties": {
                  "observed": {"type": "integer", "minimum": 0},
                  "of": {"type": "integer", "minimum": 5}
                }
              }
            ]
          },
          "early_traction": {"$ref": "#/definitions/score"},
          "unsolicited_inbound_count": {"type": "integer", "minimum": 0},
          "total": {"type": "integer", "minimum": 3, "maximum": 15},
          "clears_bar": {"type": "boolean"}
        },
        "if": {"properties": {"icp_density_sample": {"type": "null"}}},
        "then": {"properties": {"icp_density": {"const": 1}}}
      }
    },
    "outcome": {"type": "string", "enum": ["bet", "no_bet"]},
    "bet": {
      "anyOf": [
        {"type": "null"},
        {
          "type": "object",
          "required": ["channel", "start_date", "end_date", "weekly_unit", "checkpoints", "kill_criterion"],
          "additionalProperties": false,
          "properties": {
            "channel": {"$ref": "#/definitions/tactic"},
            "start_date": {"$ref": "#/definitions/date"},
            "end_date": {"$ref": "#/definitions/date"},
            "weekly_unit": {
              "type": "object",
              "required": ["count", "unit"],
              "additionalProperties": false,
              "properties": {
                "count": {"type": "integer", "minimum": 1},
                "unit": {"type": "string", "minLength": 5}
              }
            },
            "checkpoints": {
              "type": "array",
              "minItems": 2,
              "maxItems": 2,
              "items": {
                "type": "object",
                "required": ["week", "metric", "expected"],
                "additionalProperties": false,
                "properties": {
                  "week": {"type": "integer", "enum": [4, 8]},
                  "metric": {"type": "string", "minLength": 3},
                  "expected": {"type": "number", "minimum": 0}
                }
              },
              "allOf": [{"contains": {"properties": {"week": {"const": 4}}}}, {"contains": {"properties": {"week": {"const": 8}}}}]
            },
            "kill_criterion": {
              "type": "object",
              "required": ["week", "written_on", "conditions", "action", "revised"],
              "additionalProperties": false,
              "properties": {
                "week": {"const": 12},
                "written_on": {"$ref": "#/definitions/date"},
                "conditions": {
                  "type": "array",
                  "minItems": 1,
                  "items": {
                    "type": "object",
                    "required": ["metric", "operator", "value"],
                    "additionalProperties": false,
                    "properties": {
                      "metric": {"type": "string", "minLength": 3},
                      "operator": {"type": "string", "enum": ["<", "<="]},
                      "value": {"type": "number", "minimum": 0}
                    }
                  }
                },
                "action": {"const": "rerun_rubric_with_result_as_early_traction"},
                "revised": {"const": false}
              }
            }
          }
        }
      ]
    },
    "no_bet_route": {
      "anyOf": [
        {"type": "null"},
        {
          "type": "object",
          "required": ["route", "highest_scorer"],
          "additionalProperties": false,
          "properties": {
            "route": {"type": "string", "enum": ["discovery", "instrument_highest_scorer"]},
            "highest_scorer": {"$ref": "#/definitions/tactic"}
          }
        }
      ]
    },
    "parking_lot": {
      "type": "object",
      "required": ["channels", "active_work_allowed"],
      "additionalProperties": false,
      "properties": {
        "channels": {
          "type": "array",
          "items": {
            "type": "object",
            "required": ["channel", "total"],
            "additionalProperties": false,
            "properties": {
              "channel": {"$ref": "#/definitions/tactic"},
              "total": {"type": "integer", "minimum": 3, "maximum": 15}
            }
          }
        },
        "active_work_allowed": {"const": false}
      }
    }
  },
  "allOf": [
    {"if": {"properties": {"outcome": {"const": "bet"}}}, "then": {"properties": {"bet": {"type": "object"}, "no_bet_route": {"type": "null"}}}},
    {"if": {"properties": {"outcome": {"const": "no_bet"}}}, "then": {"properties": {"bet": {"type": "null"}, "no_bet_route": {"type": "object"}}}}
  ]
}

example.code:
{
  "selected_on": "2026-09-14",
  "rubric_location": "repo:founder-ops/decisions/2026-09-14-channel-bet.md",
  "working_channel_exists": false,
  "icp_sample": {"paying_customers": 11, "qualified_conversations": 23},
  "candidates": [
    {"channel": "LinkedIn founder posts on ops-team tooling", "taxonomy_channel": "content_marketing", "founder_fit": 4, "icp_density": 4, "icp_density_sample": {"observed": 7, "of": 11}, "early_traction": 4, "unsolicited_inbound_count": 3, "total": 12, "clears_bar": true},
    {"channel": "cold email to operations managers at 50-200 person logistics firms", "taxonomy_channel": "sales", "founder_fit": 3, "icp_density": 3, "icp_density_sample": {"observed": 4, "of": 11}, "early_traction": 2, "unsolicited_inbound_count": 0, "total": 8, "clears_bar": false},
    {"channel": "SEO comparison pages against the two incumbent tools", "taxonomy_channel": "seo", "founder_fit": 2, "icp_density": 3, "icp_density_sample": {"observed": 3, "of": 11}, "early_traction": 1, "unsolicited_inbound_count": 0, "total": 6, "clears_bar": false},
    {"channel": "answering questions in two ops-manager Slack communities", "taxonomy_channel": "community_building", "founder_fit": 4, "icp_density": 2, "icp_density_sample": {"observed": 2, "of": 11}, "early_traction": 2, "unsolicited_inbound_count": 1, "total": 8, "clears_bar": false}
  ],
  "outcome": "bet",
  "bet": {
    "channel": "LinkedIn founder posts on ops-team tooling",
    "start_date": "2026-09-14",
    "end_date": "2026-12-13",
    "weekly_unit": {"count": 3, "unit": "LinkedIn posts of 150 to 300 words on an ops-team tooling problem"},
    "checkpoints": [
      {"week": 4, "metric": "profile visits per week", "expected": 400},
      {"week": 8, "metric": "demo requests to date", "expected": 4}
    ],
    "kill_criterion": {
      "week": 12,
      "written_on": "2026-09-14",
      "conditions": [
        {"metric": "qualified demo requests", "operator": "<", "value": 10},
        {"metric": "new paying customers", "operator": "<", "value": 1}
      ],
      "action": "rerun_rubric_with_result_as_early_traction",
      "revised": false
    }
  },
  "no_bet_route": null,
  "parking_lot": {
    "channels": [
      {"channel": "cold email to operations managers at 50-200 person logistics firms", "total": 8},
      {"channel": "SEO comparison pages against the two incumbent tools", "total": 6},
      {"channel": "answering questions in two ops-manager Slack communities", "total": 8}
    ],
    "active_work_allowed": false
  }
}

